#!/usr/bin/env bash
set -Eeuo pipefail

if [ "$(id -u)" -ne 0 ]; then
  echo "Run this installer with sudo." >&2
  exit 1
fi
if ! command -v systemctl >/dev/null 2>&1; then
  echo "A systemd-based Ubuntu or Debian server is required." >&2
  exit 1
fi

install -d -m 0755 /opt/agent-command-center/jobs /etc/agent-command-center
install -d -m 0750 /var/lib/agent-command-center/jobs /srv/agent-command-center/workspace
if ! id agentmgr >/dev/null 2>&1; then
  useradd --system --create-home --home-dir /home/agentmgr --shell /usr/sbin/nologin agentmgr
fi

install -d -m 0755 /opt/agent-command-center
printf '%s' '' | base64 -d > /opt/agent-command-center/review-report.py
chmod 0755 /opt/agent-command-center/review-report.py
install -d -m 0755 /opt/agent-command-center
printf '%s' '' | base64 -d > /opt/agent-command-center/reports.py
chmod 0644 /opt/agent-command-center/reports.py
install -d -m 0755 /opt/agent-command-center
printf '%s' '' | base64 -d > /opt/agent-command-center/report_package.py
chmod 0644 /opt/agent-command-center/report_package.py
install -d -m 0755 /opt/agent-command-center
printf '%s' '' | base64 -d > /opt/agent-command-center/runner.py
chmod 0755 /opt/agent-command-center/runner.py
install -d -m 0755 /etc/systemd/system
printf '%s' '' | base64 -d > /etc/systemd/system/agent-command-center-runner.service
chmod 0644 /etc/systemd/system/agent-command-center-runner.service
install -d -m 0755 /opt/agent-command-center/jobs
printf '%s' '' | base64 -d > /opt/agent-command-center/jobs/preflight.sh
chmod 0755 /opt/agent-command-center/jobs/preflight.sh
install -d -m 0755 /opt/agent-command-center/jobs
printf '%s' '' | base64 -d > /opt/agent-command-center/jobs/install-dependencies.sh
chmod 0755 /opt/agent-command-center/jobs/install-dependencies.sh
install -d -m 0755 /opt/agent-command-center/jobs
printf '%s' 'IyEvdXNyL2Jpbi9lbnYgYmFzaApzZXQgLUVldW8gcGlwZWZhaWwKCm5wbSBpbnN0YWxsIC0tZ2xvYmFsIEBvcGVuYWkvY29kZXhAbGF0ZXN0CmNvZGV4IC0tdmVyc2lvbgplY2hvICJDb2RleCBDTEkgaW5zdGFsbGVkLiBBdXRoZW50aWNhdGlvbiByZW1haW5zIGEgc2VwYXJhdGUgcHJvdGVjdGVkLWNyZWRlbnRpYWwgc3RlcC4iCg==' | base64 -d > /opt/agent-command-center/jobs/install-codex.sh
chmod 0755 /opt/agent-command-center/jobs/install-codex.sh
install -d -m 0755 /opt/agent-command-center/jobs
printf '%s' 'IyEvdXNyL2Jpbi9lbnYgYmFzaApzZXQgLUVldW8gcGlwZWZhaWwKCmNvbW1hbmQgLXYgY29kZXgKY29kZXggLS12ZXJzaW9uCnJ1bnVzZXIgLXUgYWdlbnRtZ3IgLS0gY29kZXggbG9naW4gc3RhdHVzCg==' | base64 -d > /opt/agent-command-center/jobs/verify-codex.sh
chmod 0755 /opt/agent-command-center/jobs/verify-codex.sh
install -d -m 0755 /opt/agent-command-center/jobs
printf '%s' '' | base64 -d > /opt/agent-command-center/jobs/prepare-manager.sh
chmod 0755 /opt/agent-command-center/jobs/prepare-manager.sh
install -d -m 0755 /opt/agent-command-center/jobs
printf '%s' '' | base64 -d > /opt/agent-command-center/jobs/health-check.sh
chmod 0755 /opt/agent-command-center/jobs/health-check.sh

cat > /etc/agent-command-center/runner.env <<'ENV'
ACC_RUNNER_TOKEN=__ACC_RUNNER_TOKEN__
ACC_RUNNER_HOST=127.0.0.1
ACC_RUNNER_PORT=8787
ACC_STATE_DIR=/var/lib/agent-command-center/jobs
ACC_WORKSPACE=/srv/agent-command-center/workspace
ENV
chmod 0600 /etc/agent-command-center/runner.env

cat > /etc/sudoers.d/agent-command-center-runner <<'SUDOERS'
agentmgr ALL=(root) NOPASSWD: /opt/agent-command-center/jobs/preflight.sh, /opt/agent-command-center/jobs/install-dependencies.sh, /opt/agent-command-center/jobs/install-codex.sh, /opt/agent-command-center/jobs/verify-codex.sh, /opt/agent-command-center/jobs/prepare-manager.sh, /opt/agent-command-center/jobs/health-check.sh
SUDOERS
chmod 0440 /etc/sudoers.d/agent-command-center-runner
visudo -cf /etc/sudoers.d/agent-command-center-runner

chown -R agentmgr:agentmgr /var/lib/agent-command-center /srv/agent-command-center /home/agentmgr
systemctl daemon-reload
systemctl enable --now agent-command-center-runner.service
systemctl --no-pager --full status agent-command-center-runner.service

echo
echo "Bootstrap complete. The runner listens only on 127.0.0.1:8787."
echo "Put it behind an HTTPS reverse proxy or private tunnel, then enter that HTTPS URL on the dashboard Setup page."
